<?php
$escape = static fn (mixed $value): string => htmlspecialchars((string) ($value ?? ''), ENT_QUOTES, 'UTF-8');
$value = static fn (mixed $item, string $fallback = 'No disponible'): string => $item !== null && $item !== '' ? $escape($item) : '<span class="ticket-muted">' . $escape($fallback) . '</span>';
$date = static fn (?string $item): string => $item ? date('d/m/Y H:i', strtotime($item)) : 'No disponible';
$time = static fn (?string $item): string => $item ? substr($item, 0, 5) : 'No disponible';
$money = static fn (?float $amount, ?string $currency): string => $amount === null ? 'No asignado' : '$' . number_format($amount, 2, '.', ',') . ' ' . ($currency ?: 'MXN');
$originLabels = ['contact' => 'Contacto', 'product' => 'Producto', 'promotion' => 'Promoción', 'admin' => 'Administración'];
$assigned = $ticket->assignedDisplayName ?: $ticket->assignedUsername;
$priceEditor = $ticket->priceUpdatedByDisplayName ?: $ticket->priceUpdatedByUsername ?: 'Administrador';
$messageEditor = $ticket->messageUpdatedByDisplayName ?: $ticket->messageUpdatedByUsername ?: 'Administrador';
$totalPrice = $ticket->priceTotalAmount ?? $ticket->priceAmount;
$duration = 'No disponible';
if ($ticket->serviceStartTime && $ticket->serviceEndTime) {
    $minutes = (strtotime($ticket->serviceEndTime) - strtotime($ticket->serviceStartTime)) / 60;
    $duration = $minutes > 0 ? (int) floor($minutes / 60) . ' h ' . ((int) $minutes % 60) . ' min' : 'No disponible';
}
?>
<section class="section">
