                <div class="ticket-section__eyebrow">Precio</div><div class="ticket-section-card__header"><div><h2 class="ticket-section__title">Resumen fiscal</h2><p class="ticket-section-card__intro">El total final se calcula con base en el tipo de cliente actual.</p></div><?php if ($totalPrice !== null): ?><div class="ticket-price-highlight"><span class="ticket-price-highlight__label">Total final</span><span class="ticket-price"><?php echo $escape($money($totalPrice, $ticket->priceCurrency)); ?></span></div><?php endif; ?></div>
                <?php if ($totalPrice === null): ?><div class="ticket-empty-state"><strong>Sin precio asignado</strong><p>Cuando captures un precio base, el total final se recalculará automáticamente.</p></div><?php else: ?><div class="ticket-summary-grid ticket-summary-grid--compact"><div class="ticket-kv"><span class="ticket-kv__label">Precio base</span><span class="ticket-kv__value"><?php echo $escape($money($ticket->priceBaseAmount, $ticket->priceCurrency)); ?></span></div><div class="ticket-kv"><span class="ticket-kv__label">IVA</span><span class="ticket-kv__value"><?php echo $escape($money($ticket->priceIvaAmount, $ticket->priceCurrency)); ?></span></div><div class="ticket-kv"><span class="ticket-kv__label">ISR retenido</span><span class="ticket-kv__value"><?php echo $ticket->customerType === 'persona_moral' ? $escape($money($ticket->priceIsrWithholdingAmount, $ticket->priceCurrency)) : 'No aplica'; ?></span></div><div class="ticket-kv"><span class="ticket-kv__label">Tipo de cliente</span><span class="ticket-kv__value"><?php echo $ticket->customerType === 'persona_moral' ? 'Persona moral' : 'Persona física'; ?></span></div></div><?php endif; ?>
                <div class="ticket-meta-note"><strong>Última actualización:</strong> <?php echo $ticket->priceUpdatedAt ? $escape($priceEditor . ' · ' . $date($ticket->priceUpdatedAt)) : '<span class="ticket-muted">Sin precio asignado</span>'; ?></div>
            </section>

            <div class="ticket-section-split">
                <section class="card panel-card ticket-section-card"><div class="ticket-section__eyebrow">Asignación</div><h2 class="ticket-section__title">Responsabilidad operativa</h2><div class="ticket-detail-list"><div class="ticket-kv"><span class="ticket-kv__label">Responsable actual</span><?php echo $assigned ? '<span class="ticket-assignee">' . $escape($assigned) . '</span>' : '<span class="ticket-muted">Sin responsable asignado</span>'; ?></div><div class="ticket-kv"><span class="ticket-kv__label">Última asignación</span><span class="ticket-kv__value"><?php echo $ticket->assignedAt ? $escape(($ticket->assignedByDisplayName ?: $ticket->assignedByUsername ?: 'Administrador') . ' · ' . $date($ticket->assignedAt)) : 'Sin asignación registrada'; ?></span></div></div></section>
                <section class="card panel-card ticket-section-card"><div class="ticket-section__eyebrow">Cita</div><h2 class="ticket-section__title">Cita con cliente</h2><div class="ticket-detail-list"><div class="ticket-kv"><span class="ticket-kv__label">Fecha de cita</span><span class="ticket-kv__value"><?php echo $ticket->appointmentDate ? $escape(date('d/m/Y', strtotime($ticket->appointmentDate))) : 'No programada'; ?></span></div><div class="ticket-kv"><span class="ticket-kv__label">Hora de cita</span><span class="ticket-kv__value"><?php echo $escape($time($ticket->appointmentTime)); ?></span></div></div></section>
