            <section class="card panel-card ticket-section-card"><div class="ticket-section__eyebrow">Adjunto</div><h2 class="ticket-section__title">Archivo relacionado</h2><?php if ($ticket->attachmentPath): ?><div class="ticket-attachment-card"><p class="ticket-section-card__intro">El archivo adjunto del ticket se mantiene disponible para consulta administrativa.</p><a href="../<?php echo $escape($ticket->attachmentPath); ?>" target="_blank" rel="noopener" class="ticket-attachment-link"><i class="fas fa-paperclip" aria-hidden="true"></i><span>Ver archivo</span></a></div><?php else: ?><div class="ticket-empty-state"><strong>Sin adjunto</strong><p>Este ticket no tiene archivo relacionado.</p></div><?php endif; ?></section>
