                <section class="card panel-card ticket-action-card"><div class="ticket-section__eyebrow">Acciones</div><h2 class="ticket-section__title ticket-section__title--compact">Responsable</h2><form method="post" class="admin-form ticket-price-form ticket-price-form--first"><input type="hidden" name="_csrf_token" value="<?php echo $csrf; ?>"><input type="hidden" name="return" value="<?php echo $escape($returnUrl); ?>"><input type="hidden" name="action" value="assignee"><div class="admin-form__group"><label class="admin-form__label" for="assigned_user_id">Asignar / cambiar responsable</label><select id="assigned_user_id" name="assigned_user_id" class="admin-form__input" required><option value="">Selecciona un responsable</option><?php foreach ($assignableUsers as $user): ?><?php if ($user->active): ?><option value="<?php echo (int) $user->id; ?>" <?php echo $ticket->assignedUserId === $user->id ? 'selected' : ''; ?>><?php echo $escape($user->displayName ?: $user->username); ?></option><?php endif; ?><?php endforeach; ?></select><?php if ($viewerRole !== 'admin'): ?><div class="ticket-meta">Al transferir este ticket dejará de aparecer en tu bandeja.</div><?php endif; ?></div><button type="submit" class="btn">Guardar responsable</button></form></section>
